#!/usr/bin/env python3
"""tools/perm/diff.py DIR FUNC OUTPUT: unified diff of FUNC between DIR/base.c and OUTPUT/source.c, both regenerated by the
permuter's own C printer so only real changes show."""
import sys, os, difflib
sys.path.insert(0, os.path.join(os.environ["DK_TOOLCHAIN"], "src/decomp-permuter"))
from src import ast_util
from perm_pycparser import c_generator
d, func, out = sys.argv[1:4]
def fn(path):
    f, _ = ast_util.extract_fn(ast_util.parse_c(ast_util.process_pragmas(open(path).read())), func)
    return c_generator.CGenerator().visit(f).split("\n")
print("\n".join(difflib.unified_diff(fn(d + "/base.c"), fn(out + "/source.c"), lineterm="", n=1)))
